    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] preorder = new int[n], inorder = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            preorder[i] = (int) in.nval;
        }
        for (int i = 0; i < n; i++) {
            in.nextToken();
            inorder[i] = (int) in.nval;
        }
        System.out.println(String.join(" ", buildTree(preorder, inorder)));
    }
}

