def gen(rng):
    def shape(n, mode):
        L = [-1] * n
        R = [-1] * n
        if mode == 'left':
            for i in range(1, n):
                L[i - 1] = i
        elif mode == 'right':
            for i in range(1, n):
                R[i - 1] = i
        elif mode == 'zig':
            for i in range(1, n):
                if i % 2:
                    L[i - 1] = i
                else:
                    R[i - 1] = i
        elif mode == 'complete':
            for i in range(n):
                if 2 * i + 1 < n:
                    L[i] = 2 * i + 1
                if 2 * i + 2 < n:
                    R[i] = 2 * i + 2
        else:
            slots = [(0, 0), (0, 1)]
            for i in range(1, n):
                k = rng.randrange(len(slots))
                slots[k], slots[-1] = slots[-1], slots[k]
                p, s = slots.pop()
                if s == 0:
                    L[p] = i
                else:
                    R[p] = i
                slots.append((i, 0))
                slots.append((i, 1))
        return L, R

    def orders(L, R):
        pre = []
        st = [0]
        while st:
            u = st.pop()
            pre.append(u)
            if R[u] >= 0:
                st.append(R[u])
            if L[u] >= 0:
                st.append(L[u])
        ino = []
        st = []
        u = 0
        while st or u >= 0:
            while u >= 0:
                st.append(u)
                u = L[u]
            u = st.pop()
            ino.append(u)
            u = R[u]
        return pre, ino

    def make(n, mode):
        L, R = shape(n, mode)
        vals = rng.sample(range(-10**6, 10**6 + 1), n)
        pre, ino = orders(L, R)
        return str(n) + '\n' + ' '.join(str(vals[u]) for u in pre) + '\n' + ' '.join(str(vals[u]) for u in ino)

    tests = [make(1, 'random'), make(2, 'left'), make(2, 'right'), make(3, 'complete'),
             make(5, 'zig'), make(7, 'complete'), make(6, 'left'), make(6, 'right')]
    for _ in range(30):
        tests.append(make(rng.randint(2, 14), rng.choice(['random', 'random', 'left', 'right', 'zig', 'complete'])))
    for mode in ('random', 'left', 'right', 'zig'):
        tests.append(make(100000, mode))
    return tests
